import { defineStore } from 'pinia';
import { supplierStatisticApiService } from 'src/services';
import { useSettingStore } from 'src/store/main';

export interface SupplierStat {
  supplier_name: string;
  total_shipments: number;
  on_time_shipments: number;
  delayed_shipments: number;
  delayed_value: number;
  average_lateness_days: number;
  otif_percentage: number;
  delayed_shipments_percentage: number;
}

export const useSupplierDeliveryStatisticStore = defineStore(
  'supplier_delivery_statistic_store',
  {
    state: () => ({
      allRows: [] as SupplierStat[],
      rows: [] as SupplierStat[],
      loading: false,
      errorMsg: '',

      pagination_size: 10,
      current_page: 1,
      total_count: 0,

      columns: [
        {
          name: 'supplier_name',
          label: 'supplier_name',
          field: 'supplier_name',
          align: 'left' as const,
          sticky: true,
        },
        {
          name: 'otif_percentage',
          label: 'supplier_OTIF',
          field: 'otif_percentage',
          align: 'right' as const,
          format: (v: number) => `${v}%`,
        },
        {
          name: 'delayed_shipments_percentage',
          label: 'supplier_delayed_shipments_percentage',
          field: 'delayed_shipments_percentage',
          align: 'right' as const,
          format: (v: number) => `${v}%`,
        },
        {
          name: 'delayed_value',
          label: 'supplier_delayed_value',
          field: 'delayed_value',
          align: 'right' as const,
          format: (v: number) => `$${v.toLocaleString()}`,
        },
        {
          name: 'total_shipments',
          label: 'supplier_total_shipments',
          field: 'total_shipments',
          align: 'right' as const,
          format: (v: number) => `${v}`,
        },
        {
          name: 'on_time_shipments',
          label: 'supplier_on_time_shipments',
          field: 'on_time_shipments',
          align: 'right' as const,
          format: (v: number) => `${v}`,
        },
        {
          name: 'delayed_shipments',
          label: 'supplier_delayed_shipments',
          field: 'delayed_shipments',
          align: 'right' as const,
          format: (v: number) => `${v}`,
        },
        {
          name: 'average_lateness_days',
          label: 'supplier_avg_late_days',
          field: 'average_lateness_days',
          align: 'right' as const,
          format: (v: number) => `${v} days`,
        },
      ],
      // Chart data
      otifChartSeries: [] as { name: string; data: number[] }[],
      delayedChartSeries: [] as { name: string; data: number[] }[],

      // Chart options
      otifChartOptions: {} as any,
      delayedChartOptions: {} as any,

      // Constants - will be calculated dynamically
      supplierAvgOtif: 0,
    }),

    getters: {
      // Pagination
      paginatedRows: (state) => state.rows, // Paginated rows for display

      totalPages: (state) =>
        Math.ceil(state.total_count / state.pagination_size) || 1,

      // Calculate average OTIF from all data
      calculatedSupplierAvgOtif: (state) => {
        const vals = state.allRows.map(
          (r: SupplierStat) => Number(r.otif_percentage) || 0,
        );
        if (vals.length === 0) return 0;
        return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
      },

      summaryText: (state) => {
        // Calculate average OTIF of worst performing suppliers (bottom 5)
        const worstSuppliers = [...state.allRows]
          .sort((a, b) => (a.otif_percentage ?? 0) - (b.otif_percentage ?? 0))
          .slice(0, 5);

        const worstAvgOtif =
          worstSuppliers.length > 0
            ? Math.round(
                worstSuppliers
                  .map((r) => Number(r.otif_percentage) || 0)
                  .reduce((a, b) => a + b, 0) / worstSuppliers.length,
              )
            : 0;

        // Use the calculated supplier average OTIF (overall average)
        const calculatedAvg = state.supplierAvgOtif;

        const diff = worstAvgOtif - calculatedAvg;
        const diffAbs = Math.abs(diff);
        const uniqueSuppliers = worstSuppliers
          .slice(0, 3)
          .map((r) => r.supplier_name);

        // Return a structured object for translation
        return {
          suppliers: uniqueSuppliers.join(', '),
          diffAbs,
          comparison: diff < 0 ? 'lower' : 'higher',
          avgOtif: calculatedAvg,
        };
      },

      worstAvgOtif: (state) => {
        const vals = state.allRows.map(
          (r: SupplierStat) => Number(r.otif_percentage) || 0,
        );
        if (vals.length === 0) return 0;
        return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
      },

      bestByOtif: (state) => {
        return [...state.allRows]
          .sort((a, b) => (b.otif_percentage ?? 0) - (a.otif_percentage ?? 0))
          .slice(0, 5);
      },

      worstByDelayed: (state) => {
        return [...state.allRows]
          .sort(
            (a, b) =>
              (b.delayed_shipments_percentage ?? 0) -
              (a.delayed_shipments_percentage ?? 0),
          )
          .slice(0, 5);
      },
    },

    actions: {
      // Pagination actions
      setPage(page: number) {
        this.current_page = page;
        this.updatePaginatedRows(); // Update pagination without reloading data
      },

      setPaginationSize(size: number) {
        // Calculate the index of the first currently visible record
        const currentFirstRecordIndex =
          (this.current_page - 1) * this.pagination_size;

        this.pagination_size = size;

        // Calculate which page the first currently visible record should be on with new pagination size
        const newPageForFirstRecord =
          Math.floor(currentFirstRecordIndex / this.pagination_size) + 1;
        const newTotalPages =
          Math.ceil(this.total_count / this.pagination_size) || 1;

        // Set the page to keep the same records visible
        this.current_page = Math.min(newPageForFirstRecord, newTotalPages);

        // Force update pagination
        this.updatePaginatedRows();
      },

      // Data loading
      async loadSupplierStatistics() {
        this.loading = true;
        this.errorMsg = '';

        try {
          // Load pagination settings first
          await this.getPaginationSize();

          // Fetch all data from server (no pagination parameters)
          const resp =
            (await supplierStatisticApiService.getSupplierStatistics()) as {
              success?: boolean;
              data?: SupplierStat[];
              total_count?: number;
            };

          const allData: SupplierStat[] = Array.isArray(resp?.data)
            ? resp.data
            : [];
          this.allRows = allData;
          this.total_count = allData.length; // Total count is now the length of all data

          // Apply client-side pagination
          this.updatePaginatedRows();

          // Update chart data
          this.updateChartData();

          // Update the calculated average OTIF
          this.updateSupplierAvgOtif();
        } catch (e: any) {
          this.errorMsg = 'Failed to load supplier statistics.';
        } finally {
          this.loading = false;
        }
      },

      // Client-side pagination: update rows based on current page and page size
      updatePaginatedRows() {
        // Ensure we have data to paginate
        if (!this.allRows || this.allRows.length === 0) {
          this.rows = [];
          return;
        }

        // Ensure current page is valid
        const maxPage = Math.ceil(this.total_count / this.pagination_size) || 1;

        if (this.current_page > maxPage) {
          this.current_page = maxPage;
        }
        if (this.current_page < 1) {
          this.current_page = 1;
        }

        const startIndex = (this.current_page - 1) * this.pagination_size;
        const endIndex = startIndex + this.pagination_size;

        this.rows = this.allRows.slice(startIndex, endIndex);
      },

      // Update supplier average OTIF from all data
      updateSupplierAvgOtif() {
        if (this.allRows.length > 0) {
          const avgOtif =
            this.allRows
              .map((r) => Number(r.otif_percentage) || 0)
              .reduce((a, b) => a + b, 0) / this.allRows.length;
          this.supplierAvgOtif = Math.round(avgOtif);
        } else {
          this.supplierAvgOtif = 0;
        }
      },

      // Chart data updates
      updateChartData() {
        // OTIF chart
        const otifCats = this.bestByOtif.map((r) => r.supplier_name);
        const otifVals = this.bestByOtif.map((r) => r.otif_percentage ?? 0);
        this.otifChartSeries = [{ name: 'OTIF', data: otifVals }];

        // Delayed shipments chart
        const delayedCats = this.worstByDelayed.map((r) => r.supplier_name);
        const delayedVals = this.worstByDelayed.map(
          (r) => r.delayed_shipments_percentage ?? 0,
        );
        this.delayedChartSeries = [
          { name: 'Delayed Shipments', data: delayedVals },
        ];

        // Update chart options with categories
        if (this.otifChartOptions.xaxis) {
          this.otifChartOptions = {
            ...this.otifChartOptions,
            xaxis: {
              ...this.otifChartOptions.xaxis,
              categories: otifCats,
            },
          };
        }

        if (this.delayedChartOptions.xaxis) {
          this.delayedChartOptions = {
            ...this.delayedChartOptions,
            xaxis: {
              ...this.delayedChartOptions.xaxis,
              categories: delayedCats,
            },
          };
        }
      },

      // Chart options management
      updateChartOptions(otifOptions: any, delayedOptions: any) {
        this.otifChartOptions = otifOptions;
        this.delayedChartOptions = delayedOptions;
      },

      // Error handling
      clearError() {
        this.errorMsg = '';
      },

      // Reset functions
      resetData() {
        this.rows = [];
        this.errorMsg = '';
        this.otifChartSeries = [];
        this.delayedChartSeries = [];
        this.current_page = 1;
        this.total_count = 0;
      },

      // Settings management
      async getPaginationSize() {
        const settings_store = useSettingStore();
        const pagination_size_setting =
          await settings_store.getUserBasedSettings('PAGINATION_SIZE');
        if (
          isNaN(pagination_size_setting) ||
          typeof pagination_size_setting === 'object' ||
          !pagination_size_setting
        ) {
          this.pagination_size = 10;
        } else {
          this.pagination_size = pagination_size_setting;
        }
        return Number(this.pagination_size);
      },

      async setPaginationSizeSetting() {
        const settings_store = useSettingStore();
        await settings_store.setUserPreferences(
          'PAGINATION_SIZE',
          this.pagination_size <= 50 ? this.pagination_size : '50',
        );
      },
    },
  },
);
