<template>
  <SubHeader
    name="supplier_statistics"
    :label="$t('supplier_statistics')"
    :onSearch="false"
    :display_help_link="false"
  />
  <div class="q-pa-sm page-height-limit_2">
    <div class="row q-col-gutter-md">
      <div class="col-12">
        <q-card flat bordered class="ai-summary">
          <q-card-section class="text-subtitle1 text-weight-medium">
            {{
              $t('supplier_summary_text', {
                ...summaryText,
                comparison: $t(summaryText.comparison),
              })
            }}
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-md-8">
        <q-card flat bordered class="q-pa-md no-padding-bottom">
          <div class="text-subtitle2 q-mb-sm">
            {{ $t('supplier_worst_performing') }}
          </div>
          <div class="table-container">
            <DocBitsTable
              :rows="paginatedRows"
              :columns="translatedColumns"
              row-key="supplier_name"
              table-id="supplier_delivery_statistic_table"
              :features="{
                sorting: false,
                filtering: false,
                selection: false,
                bulkActions: false,
                rowActions: false,
                resizable: false,
                pagination: false,
                columnReorder: false,
              }"
              no-data-label="no_record_found"
              flat-style
            >
              <template #body-cell-supplier_name="{ row }">
                <span class="supplier-name-text" :title="row.supplier_name">{{ row.supplier_name }}</span>
              </template>
            </DocBitsTable>
          </div>
          <div class="back-white flex justify-end">
            <div class="row items-center" style="margin-right: 0">
              <PaginationSettings class="q-py-xs q-mr-md" />
              <q-separator vertical />
              <q-pagination
                v-model="DeliveryStatisticStore.current_page"
                :max="totalPages"
                color="primary"
                class="q-py-xs q-mx-md"
                :max-pages="6"
                input
                boundary-links
                @update:model-value="DeliveryStatisticStore.setPage"
              />
            </div>
          </div>
        </q-card>
      </div>

      <div class="col-12 col-md-4 right-col">
        <q-card flat bordered class="q-pa-md half-card">
          <div class="text-subtitle2 q-mb-sm">{{ $t('supplier_OTIF') }}</div>
          <div>
            <apexchart
              type="bar"
              height="150%"
              :options="otifChartOptions"
              :series="otifChartSeries"
            ></apexchart>
          </div>
        </q-card>
        <q-card flat bordered class="q-pa-md half-card">
          <div class="text-subtitle2 q-mb-sm">
            {{ $t('supplier_delayed_shipments') }}
          </div>
          <div>
            <apexchart
              type="bar"
              height="150%"
              :options="delayedChartOptions"
              :series="delayedChartSeries"
            ></apexchart>
          </div>
        </q-card>
      </div>
    </div>
  </div>

  <!-- Loading Screen -->
  <q-inner-loading :showing="loading" style="z-index: 1000000000">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import VueApexCharts from 'vue3-apexcharts';
import { useSupplierDeliveryStatisticStore } from './supplierDeliveryStatisticComponents/store';
import { storeToRefs } from 'pinia';
import PaginationSettings from './supplierDeliveryStatisticComponents/components/PaginationSettings.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';

export default defineComponent({
  name: 'SupplierDeliveryStatistic',
  components: {
    SubHeader,
    apexchart: VueApexCharts,
    PaginationSettings,
    DocBitsTable,
  },
  computed: {
    translatedColumns(): any[] {
      return (this.columns || []).map((col: any) => ({ ...col, label: this.$t(col.label) }));
    },
  },
    mounted() {
    this.initializeChartOptions();
    this.loadSupplierStatistics();
  },
  watch: {
    '$q.dark.isActive'(isDark) {
      this.initializeChartOptions();
    },
    'DeliveryStatisticStore.errorMsg'(newError) {
      if (newError) {
        notify.error(newError);
      }
    },
  },
  methods: {
    getLabelColor() {
      return this.$q.dark.isActive ? '#F3F3F3' : '#222';
    },
    getTooltipTheme() {
      return this.$q.dark.isActive ? 'dark' : 'light';
    },
    initializeChartOptions() {
      const existingOtifCategories =
        this.otifChartOptions?.xaxis?.categories || [];
      const existingDelayedCategories =
        this.delayedChartOptions?.xaxis?.categories || [];

      const otifOptions = {
        chart: { toolbar: { show: false } },
        dataLabels: { enabled: false },
        plotOptions: { bar: { horizontal: true } },
        xaxis: {
          categories: existingOtifCategories,
          labels: {
            formatter: (v: number) => `${Math.round(v)}%`,
            style: { colors: this.getLabelColor() },
          },
        },
        yaxis: {
          labels: { style: { colors: this.getLabelColor() } },
        },
        tooltip: {
          theme: this.getTooltipTheme(),
          style: { color: this.getLabelColor() },
        },
      };

      const delayedOptions = {
        chart: { toolbar: { show: false } },
        dataLabels: { enabled: false },
        plotOptions: { bar: { horizontal: true } },
        xaxis: {
          categories: existingDelayedCategories,
          labels: {
            formatter: (v: any) => `${Math.round(Number(v))}%`,
            style: { colors: this.getLabelColor() },
          },
        },
        yaxis: {
          labels: { style: { colors: this.getLabelColor() } },
        },
        tooltip: {
          theme: this.getTooltipTheme(),
          style: { color: this.getLabelColor() },
        },
      };

      this.updateChartOptions(otifOptions, delayedOptions);
    },
  },
  setup() {
    // Initialize store
    const DeliveryStatisticStore = useSupplierDeliveryStatisticStore();
    const {
      columns,
      paginatedRows,
      totalPages,
      summaryText,
      otifChartSeries,
      otifChartOptions,
      delayedChartSeries,
      delayedChartOptions,
      loading,
    } = storeToRefs(DeliveryStatisticStore);

    const { loadSupplierStatistics, updateChartOptions } =
      DeliveryStatisticStore;

    return {
      DeliveryStatisticStore,
      columns,
      paginatedRows,
      totalPages,
      summaryText,
      otifChartSeries,
      otifChartOptions,
      delayedChartSeries,
      delayedChartOptions,
      loading,
      loadSupplierStatistics,
      updateChartOptions,
    };
  },
});
</script>

