<template>
  <div class="row items-center">
    <span class="q-py-xs q-mr-sm">{{ $t('supplier_per_page') }}:</span>
    <q-select
      borderless
      dense
      v-model="pagination_size"
      :options="pagination_options"
      @update:model-value="(val) => updatePaginationSize(val)"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSupplierDeliveryStatisticStore } from '../store';

export default defineComponent({
  mixins: [],
  props: {},

  methods: {
    validatePaginationSize() {
      if (this.pagination_size <= 50) return;
      this.pagination_size = 50;
    },
    async updatePaginationSize(newValue: string | number) {
      const numericValue = Number(newValue);
      this.validatePaginationSize();
      await this.setPaginationSizeSetting();
      this.setPaginationSize(numericValue);
    },
  },

  mounted() {
    this.validatePaginationSize();
  },

  setup() {
    const store = useSupplierDeliveryStatisticStore();
    const { pagination_size } = storeToRefs(store);
    const { setPaginationSizeSetting, setPaginationSize } = store;

    return {
      pagination_size,
      setPaginationSizeSetting,
      setPaginationSize,
      pagination_options: ref(['10', '20', '25', '50']),
    };
  },
});
</script>

<style lang="scss">
.user-select {
  width: 227px;
}
</style>
